"""Load the search-workflow authoring guide bundled with Paperclip."""

from __future__ import annotations

import pkgutil
from pathlib import Path


def load_search_config_guide() -> str:
    """Return the guide from package data or directly from a source checkout."""
    try:
        bundled = pkgutil.get_data(
            "gxl_paperclip", "resources/search_config_guide.md"
        )
    except OSError:
        bundled = None
    if bundled is not None:
        return bundled.decode("utf-8")

    source_guide = (
        Path(__file__).resolve().parents[3]
        / "examples"
        / "search_configs"
        / "README.md"
    )
    try:
        return source_guide.read_text(encoding="utf-8")
    except OSError as exc:
        raise RuntimeError("Search config guide is missing from this installation") from exc
